  `thickness` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `height` double DEFAULT NULL,
  `width` double DEFAULT NULL,
  `grain_direction` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `edge_bevel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wing_area` double DEFAULT NULL,
  `molding_length` double DEFAULT NULL,
  `quantity` int NOT NULL DEFAULT '1',
  `unit_price` double NOT NULL DEFAULT '0',
  `total_price` double NOT NULL DEFAULT '0',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `old_size` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bevel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
