  `offset_top` int DEFAULT NULL,
  `offset_bottom` int DEFAULT NULL,
  `mill_left` int DEFAULT NULL,
  `mill_right` int DEFAULT NULL,
  `mill_top` int DEFAULT NULL,
  `mill_bottom` int DEFAULT NULL,
  `mill_width` int DEFAULT NULL,
