INSERT INTO `minlate_prices` VALUES (93,'ÉP MẶT:','1','Ép mặt laminate, PVC, Verneer lên MDF  sử dụng keo chống thấm nước PUR Jowat, H.B Fuller, Technobond.','mặt',180000,NULL,NULL,'2026-07-02 13:57:38','2026-07-02 13:57:38'),(94,'ÉP MẶT:','2','Ép mặt laminate, PVC, Verneer lên cốt gỗ nhựa Picomat sử dụng keo chống thấm nước PUR Jowat, H.B Fuller, Technobond.','mặt',200000,NULL,NULL,'2026-07-02 13:57:38','2026-07-02 13:57:38'),(95,'DÁN CẠNH BẰNG KEO CHỐNG THẤM NƯỚC PUR:','1','Dán cạnh thẳng laminate, melamine sử dụng keo chống thấm nước PUR:\nÁp dụng cho tấm ván có chiều rộng từ 60mm trở lên, độ dày ván 9-21mm (không bao gồm nẹp dán cạnh) sử dụng máy dán Homag, Cộng hòa LB Đức.','m',12000,NULL,NULL,'2026-07-02 13:57:38','2026-07-02 13:57:38'),(96,'DÁN CẠNH BẰNG KEO CHỐNG THẤM NƯỚC PUR:','2','Dán cạnh thẳng laminate, melamine sử dụng keo chống thấm nước PUR:\nÁp dụng cho tấm ván có chiều rộng từ 60mm trở lên, độ dày ván 25-35mm (không bao gồm nẹp dán cạnh) sử dụng máy dán Homag, Cộng hòa LB Đức.','m',15000,NULL,NULL,'2026-07-02 13:57:38','2026-07-02 13:57:38'),(97,'DÁN CẠNH BẰNG KEO CHỐNG THẤM NƯỚC PUR:','3','Dán cạnh thẳng laminate, melamine sử dụng keo chống thấm nước PUR:\nÁp dụng cho tấm ván có chiều rộng từ 60mm trở lên, độ dày ván 40-45mm (không bao gồm nẹp dán cạnh) sử dụng keo Jowat, Kleibrit, Technobond, máy dán Homag sản xuất tại Đức.','m',22000,NULL,NULL,'2026-07-02 13:57:38','2026-07-02 13:57:38'),(98,'DÁN CẠNH BẰNG KEO CHỐNG THẤM NƯỚC PUR:','4','Dán cạnh thẳng laminate, melamine sử dụng keo chống thấm nước PUR:\nÁp dụng cho tấm ván có chiều rộng từ 40mm đến 59mm, độ dày ván 9-21mm nhân công, keo, băng dính dán cạnh thẳng laminate, melamine. (không bao gồm nẹp dán cạnh) sử dụng máy dán Homag, Cộng hòa LB Đức.','m',25000,NULL,NULL,'2026-07-02 13:57:38','2026-07-02 13:57:38'),(99,'DÁN CẠNH BẰNG KEO CHỐNG THẤM NƯỚC PUR:','5','Dán cạnh thẳng laminate, melamine sử dụng keo chống thấm nước PUR:\nÁp dụng cho tấm ván có chiều rộng từ 40mm đến 59mm, độ dày ván 25-